    "    run(\"max-heap\", {20, 8, 10, 6, 5, 3, 9}, {25}, false,",
    "        \"Max-heap. Inserisco 25, il nuovo massimo: stessa risalita, confronto rovesciato.\");",
    "",
    "    return 0;",
    "}"
